package org.apache.commons.math3.dfp;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math3.FieldElement;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.math3.dfp.Dfp#multiply(int)
 */
public class Dfp_multiply_TriageGen5Test {

    @Test
    public void testMultiply_PositiveInteger() {
        Dfp fieldInstance = Dfp.getPrecisionField(); // Assuming access to a field via static or instance
        // Since Dfp is complex, we use a known instance to get the field
        Dfp base = Dfp.getPrecisionField().newInstance(); 
        Dfp one = base.newInstance(1);
        Dfp five = base.newInstance(5);

        Dfp result = one.multiply(5);

        Assert.assertEquals("Multiplying 1 by 5 should result in 5", 5, result.intValue());
        Assert.assertTrue("Result should be equal to Dfp 5", five.equals(result));
    }

    @Test
    public void testMultiply_Zero() {
        Dfp base = Dfp.getPrecisionField().newInstance();
        Dfp ten = base.newInstance(10);
        Dfp zero = base.getZero();

        Dfp result = ten.multiply(0);

        Assert.assertTrue("Multiplying by 0 should result in 0", zero.equals(result));
        Assert.assertTrue("Result should be zero", result.isZero());
    }

    @Test
    public void testMultiply_NegativeInteger() {
        Dfp base = Dfp.getPrecisionField().newInstance();
        Dfp two = base.newInstance(2);

        Dfp result = two.multiply(-3);

        Assert.assertEquals("2 * -3 should be -6", -6, result.intValue());
        Assert.assertTrue("Result should be negative", result.strictlyNegative());
    }

    @Test
    public void testMultiply_LargeInteger() {
        Dfp base = Dfp.getPrecisionField().newInstance();
        Dfp one = base.newInstance(1);
        int largeVal = Integer.MAX_VALUE;

        Dfp result = one.multiply(largeVal);

        Assert.assertEquals("Multiplying 1 by MAX_VALUE", largeVal, result.intValue());
    }

    @Test
    public void testMultiply_NegativeByNegative() {
        Dfp base = Dfp.getPrecisionField().newInstance();
        Dfp negTwo = base.newInstance(-2);

        Dfp result = negTwo.multiply(-4);

        Assert.assertEquals("Multiplying -2 by -4 should be 8", 8, result.intValue());
        Assert.assertTrue("Result should be positive", result.positiveOrNull());
    }

    @Test
    public void testMultiply_Identity() {
        Dfp base = Dfp.getPrecisionField().newInstance();
        Dfp val = base.newInstance(12345);
        Dfp one = base.getOne();

        Dfp result = val.multiply(1);

        Assert.assertTrue("Multiplying by 1 should return same value", val.equals(result));
    }

    @Test
    public void testMultiply_DecimalContext() {
        // Testing if multiplication works on non-integer Dfp values
        Dfp base = Dfp.getPrecisionField().newInstance();
        Dfp half = base.newInstance(0.5);

        Dfp result = half.multiply(2);

        Assert.assertEquals("0.5 * 2 should be 1", 1, result.intValue());
        Assert.assertTrue("Result should be 1.0", base.newInstance(1.0).equals(result));
    }
}
